// Dart 变量、数据类型与空安全 入门示例
// 运行方式：把本文件保存为 main.dart，然后执行 `dart run main.dart`

void main() {
  // ---------- 1. 显式声明与类型推断 ----------
  int age = 18; // 显式声明为 int
  var name = '小明'; // 编译器推断为 String，之后不能再赋值成其他类型
  String greeting = '你好'; // 显式声明为 String（公开 API 推荐这种写法）

  // ---------- 2. final 与 const ----------
  final DateTime now = DateTime.now(); // 运行时确定，只能赋值一次
  const double pi = 3.14159; // 编译期常量，值必须在编译期可确定

  print('$greeting, $name！今年 $age 岁。');
  print('当前时间：$now，圆周率：$pi');

  // ---------- 3. 常用数据类型 ----------
  double score = 92.5;
  bool isPass = score >= 60;
  List<String> fruits = ['苹果', '香蕉', '橘子'];
  Map<String, int> stock = {'苹果': 12, '香蕉': 30, '橘子': 5};

  print('分数：$score，是否通过：$isPass');
  print('水果列表：$fruits');
  print('库存：$stock');

  // 数值类型转换：int 与 double 不能隐式互转
  int intScore = score.toInt(); // 92
  double doubleAge = age.toDouble(); // 18.0
  print('int 分数：$intScore，double 年龄：$doubleAge');

  // ---------- 4. 空安全（Null Safety） ----------
  String? nickname; // 可空类型，允许为 null
  print('昵称：${nickname ?? "（未填写）"}'); // ?? 在为 null 时提供默认值

  nickname = 'Dart 学徒';
  // 赋值后 Dart 的「流程分析」自动把它提升为非空 String，可以直接 .length
  print('昵称长度：${nickname.length}');

  // ---------- 5. 断言非空（!）与延迟初始化（late） ----------
  String? address;
  address = '北京';
  // ! 用于断言「我确定它不为 null」，若真为 null 会在运行时抛错
  print('地址长度：${address!.length}');

  late String profile; // 延迟初始化：稍后一定赋值，且不想声明成可空类型
  profile = 'Flutter 初学者';
  print('简介：$profile');

  // ---------- 6. 判空后自动提升 ----------
  String? email = getEmail();
  if (email != null) {
    // 进入 if 分支后，email 被自动提升为非空 String，无需再写 !
    print('邮箱（大写）：${email.toUpperCase()}');
  } else {
    print('未绑定邮箱');
  }
}

// 模拟一个可能返回 null 的函数
String? getEmail() {
  final bool hasEmail = DateTime.now().second % 2 == 0;
  return hasEmail ? 'flutter@example.com' : null;
}

